[CmdletBinding()]param([string]$ProjectRoot=".")
$ErrorActionPreference="Stop";$A=Get-Content (Join-Path (Resolve-Path $ProjectRoot).Path ".agy\REVIEWER_ATTESTATION.json") -Raw|ConvertFrom-Json;$E=@();if($A.read_only-ne$true){$E+="NOT_READ_ONLY"};if($A.implementation_context_id-eq$A.reviewer_context_id){$E+="SAME_CONTEXT"};if([IO.Path]::GetFullPath([string]$A.implementation_root).TrimEnd('\')-eq[IO.Path]::GetFullPath([string]$A.reviewer_root).TrimEnd('\')){$E+="SAME_ROOT"};if($A.predicate_origin-eq"implementation_context" -or $A.reviewer_authored_implementation -or $A.reviewer_authored_artifact_generator -or $A.reviewer_authored_predicates){$E+="SELF_REVIEW"};if($A.independence_status-ne"independent"){$E+="NOT_INDEPENDENT"};if([string]$A.artifact_manifest_sha256-notmatch'^[0-9a-f]{64}$'){$E+="BAD_MANIFEST_IDENTITY"};if($E.Count){$E|%{Write-Host "- $_"};exit 1};Write-Host "Protected reviewer attestation valid.";exit 0
